  [1, 'I'],
];

/**
 * Convert an integer in the range 1..3999 to a Roman numeral.
 * @param {number} n
 * @returns {string}
 * @throws {TypeError} if n is not a number
 * @throws {RangeError} if n is not an integer between 1 and 3999
 */
export function toRoman(n) {
  if (typeof n !== 'number') {
    throw new TypeError(`Expected a number, got ${typeof n}`);
  }
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError(`Expected an integer between 1 and 3999, got ${n}`);
  }
  let result = '';
  for (const [value, symbol] of NUMERALS) {
    while (n >= value) {
      result += symbol;
      n -= value;
    }
  }
  return result;
}
"}

{"path": "test/roman.test.js", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { toRoman } from '../src/roman.js';

test('converts basic numerals', () => {
  const cases = [
    [1, 'I'], [2, 'II'], [3, 'III'], [5, 'V'], [10, 'X'],
    [50, 'L'], [100, 'C'], [500, 'D'], [1000, 'M'],
  ];
  for (const [n, expected] of cases) assert.equal(toRoman(n), expected);
});

test('uses subtractive notation', () => {
  const cases = [
    [4, 'IV'], [9, 'IX'], [14, 'XIV'], [40, 'XL'], [90, 'XC'],
    [400, 'CD'], [900, 'CM'], [444, 'CDXLIV'], [999, 'CMXCIX'],
  ];
  for (const [n, expected] of cases) assert.equal(toRoman(n), expected);
});

test('converts composite and boundary values', () => {
  assert.equal(toRoman(58), 'LVIII');
  assert.equal(toRoman(1994), 'MCMXCIV');
  assert.equal(toRoman(2024), 'MMXXIV');
  assert.equal(toRoman(3888), 'MMMDCCCLXXXVIII');
  assert.equal(toRoman(3999), 'MMMCMXCIX');
});

test('produces unique, well-formed output for every value in range', () => {
  const seen = new Set();
  const valid = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;
  for (let n = 1; n <= 3999; n++) {
    const r = toRoman(n);
    assert.match(r, valid);
    assert.ok(!seen.has(r), `duplicate numeral ${r}`);
    seen.add(r);
  }
});

test('throws RangeError outside 1..3999', () => {
  for (const n of [0, -1, 4000, 10000, Infinity, -Infinity]) {
    assert.throws(() => toRoman(n), RangeError);
  }
});

test('throws RangeError for non-integers and NaN', () => {
  for (const n of [1.5, 3998.9, NaN]) {
    assert.throws(() => toRoman(n), RangeError);
  }
});

test('throws TypeError for non-number input', () => {
  for (const v of ['10', null, undefined, 10n, {}]) {
    assert.throws(() => toRoman(v), TypeError);
  }
});
"}
